  enum Color { red, green }
  datatype S { ok: bool; n: int; xs: int[2]; }
  datatype W { s: S; }
  port def Api { provides operation get(out v: int); }
  component def Twin { attribute link: bool = false; attribute snap: S = record S { ok = false; n = 0; xs = [0, 0]; }; operation join() { link = true; } }
  component def Backend { component twins: Twin[2]; component single: Twin; attribute k: int = 3; }
