    attribute a: int[3] = [1, 2, 3];
    attribute r: S = record S { ok = false; n = 4; xs = [5, 6]; };
    attribute w: W = record W { s = record S { ok = true; n = 7; xs = [8, 9]; }; };
    attribute out1: int = 0;
    const attribute c: int[2] = [1, 2];
    operation put(out v: int) { v = 42; }
    operation run() {
      var i: int = 1;
      out1 = a[i] + r.n + r.xs[i] + w.s.xs[0] + w.s.n;
      put(out1);
      a = [a[2], a[1], a[0]];
      r = record S { ok = true; n = r.xs[1]; xs = r.xs; };
    }
    schedule { on start run(); }
  }
  component Demo: D;
  component backend: Backend;

}

